-- 云端重复销售只读预览（2026-11-21）
-- 只查询来源事件精确匹配的销售ID及其关联，不包含 DELETE。
-- 同 SN 多行不等于重复；需先确认来源事件映射。
SET @preview_only = 1;

-- 来源事件=8549d92515a6516bbebd595b | SN=C02L7KQEF5V7 | 日期=2023-11-02 | 买家=胡瑶 | 手机=15159876150 | 售价=1900.00
SELECT s.id sale_id,s.phone_id device_id,p.serial_number,s.sale_time,s.sale_price,c.name,c.phone,ns.id subsidy_id,pr.id payment_id,cpe.id points_id,sa.id aftersale_id FROM sales s LEFT JOIN phones p ON p.id=s.phone_id LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN national_subsidies ns ON ns.sale_id=s.id LEFT JOIN payment_records pr ON pr.order_id=s.id LEFT JOIN customer_points_entries cpe ON cpe.source_type='phone_sale' AND cpe.source_id=s.id LEFT JOIN sales_aftersales sa ON sa.order_id=s.id WHERE s.id IN (1948,2898) ORDER BY s.id;

